import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.2EHAL5nC.js";const u=JSON.parse('{"title":"Limitations","description":"","frontmatter":{},"headers":[],"relativePath":"reference/limitations.md","filePath":"reference/limitations.md","lastUpdated":1794899297000}'),r={name:"reference/limitations.md"};function s(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h1><p>What RustCMS does not do yet, the fixed limits it enforces, and behaviours to know before relying on it. Read it when you plan an application, so a limit does not surprise you in production.</p><h2 id="not-supported-yet" tabindex="-1">Not supported yet <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported yet&quot;">​</a></h2><ul><li>Pivot columns in the record&#39;s own form (a <code>BelongsToManySelect</code> links with the pivot&#39;s database defaults; edit pivot columns in the relation manager), and a <code>BelongsToManySelect</code> for relations with required pivot fields or records with more than 100 links; belongs-to-many to the same resource, two relations over one pivot table, or to a resource declaring <code>lock_parent</code>.</li><li>Excel files; dashboard widgets with sums or averages (widgets count or list records); charts in time zones other than UTC.</li><li>Email verification flows (invitations mark the address verified).</li><li>Mail rate limits shared between instances (<code>max_per_minute</code> counts per process); DKIM signing; attachments.</li><li>Settings of kinds other than text, textarea, integer (<code>i32</code>), boolean, select, key/value, date, secret and media (one file, or a list) (store larger numbers or decimals as text).</li><li>Translations of content (only the interface is translated: English, Vietnamese).</li><li>Composite primary keys; sorting by related columns.</li><li>Column types without a wire kind: <code>smallint</code>, <code>tinyint</code>, unsigned integers, <code>time</code>, binary, enums and arrays cannot be admin fields (<a href="./wire-format.html#unsupported-column-types">Wire format</a>).</li><li>Server-side image resizing (the Media grid scales the originals in the browser), range requests, presigned or public media URLs (files are served only through the panel, after an authorization check; add your own route for public files).</li><li>MariaDB; Redis Cluster.</li><li>Idempotency keys outside resource creates (relation creates included), actions, media uploads, CSV import uploads and background export requests.</li><li>Managing API-guard roles from the panel (use <code>rustcms role:assign</code>).</li><li>Cron expressions in a time zone other than UTC.</li></ul><h2 id="fixed-limits" tabindex="-1">Fixed limits <a class="header-anchor" href="#fixed-limits" aria-label="Permalink to &quot;Fixed limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th><th>Where</th></tr></thead><tbody><tr><td>Rows a list, export or dashboard count checks one by one (per-record policies, trashed lists, SQLite dated counts)</td><td>10,000</td><td>beyond: 422 <code>too_many_matches</code> for lists and exports at once, a background export failed as <code>too_many_matches</code>, a <code>too_many</code> widget on the dashboard (<a href="./admin-api.html#limits">Admin API</a>)</td></tr><tr><td>Rows of a background export</td><td>10,000</td><td>beyond: the export fails as <code>too_many_to_export</code> (<a href="./../admin/import-export.html#at-once-or-in-the-background">Import and export</a>)</td></tr><tr><td>Keys per action or lookup</td><td>500 (100 for a field&#39;s options lookup)</td><td><a href="./admin-api.html#limits">Admin API</a></td></tr><tr><td>Keys per attach or detach</td><td>100</td><td><a href="./../admin/relationships.html">Relationships</a></td></tr><tr><td><code>per_page</code></td><td>100</td><td><a href="./admin-api.html#lists">Admin API</a></td></tr><tr><td>Recipients of one mail</td><td>50</td><td><a href="./../digging-deeper/mail.html">Mail</a></td></tr><tr><td>An encrypted value (its JSON)</td><td>32 KiB; never searched, sorted or filtered</td><td><a href="./../digging-deeper/encryption.html#pitfalls-and-limits">Encrypted columns</a></td></tr><tr><td>Live idempotency keys per user</td><td>1,000 (429 beyond)</td><td><a href="./admin-api.html#retrying-writes-safely">Admin API</a></td></tr><tr><td>Rows of a relationship repeater</td><td><code>max_items</code> in the form (at most 100); a save reorders at most 1,000 rows of one parent</td><td>more rows: the repeater is read-only; beyond 1,000: 422 <code>too_many_rows</code> (<a href="./../admin/forms.html#repeaters">Forms</a>)</td></tr><tr><td>Computed values (<code>computed()</code>)</td><td>5 s each (<code>.timeout</code>, at most 30 s); 60 view pages a minute per user, 2 at once per user, 8 at once in all</td><td>beyond: the value shows &quot;Not available&quot; (<a href="./../admin/infolists.html#computed-values">Infolists</a>)</td></tr></tbody></table><h2 id="writes-in-flight" tabindex="-1">Writes in flight <a class="header-anchor" href="#writes-in-flight" aria-label="Permalink to &quot;Writes in flight&quot;">​</a></h2><p>Signing out one session, or revoking one API token, does not abort a change that the same credential already started. Sign-out everywhere, password changes and disabling a user apply from the next request (with the opt-in <code>auth.jwt.session_cache_ms</code> and <code>auth.permission_generation_cache_ms</code>, within those times on other instances, see <a href="./../security/revocation.html#several-instances">Credential revocation</a>), and changes made through <code>RbacService</code> re-check the credential under lock. A resource write keeps the permissions it started with.</p><h2 id="background-work" tabindex="-1">Background work <a class="header-anchor" href="#background-work" aria-label="Permalink to &quot;Background work&quot;">​</a></h2><ul><li>Schedules run only in <code>rustcms serve</code>, never in console commands, <code>queue:work</code> or tests (<a href="./../digging-deeper/scheduling.html">Scheduling</a>).</li><li>The auth, idempotency, media and exports clean-ups are framework schedules, run only by <code>serve</code> with the scheduler: a deployment without it runs them from cron (<a href="./../operations/retention.html#from-cron">Data retention</a>). Each instance sweeps the files it staged itself (<code>serve</code>, <code>queue:work</code>).</li></ul><h2 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h2><ul><li><strong>SQLite decimals</strong> are stored as REAL: values are shown at the column scale, but precision is that of a 64-bit float. Use PostgreSQL or MySQL for money.</li><li><strong>Search</strong> compares <code>LOWER(column) LIKE LOWER(pattern)</code>: case-insensitive for all of Unicode on PostgreSQL, for ASCII only on SQLite. It uses no index; full-text search is out of scope.</li><li><strong>Named locks on MySQL</strong>: <code>rustcms::db::xact_lock</code> works only with the names the framework creates (<code>rbac</code>, <code>lineage:&lt;slot&gt;</code>, <code>idem:&lt;slot&gt;</code>); other names fail on MySQL (<a href="./database-schema.html#rustcms_locks">Database schema</a>).</li><li>MySQL specifics (collation, non-transactional DDL) are in <a href="./../basics/database.html#mysql">Database</a>.</li></ul><h2 id="deployments" tabindex="-1">Deployments <a class="header-anchor" href="#deployments" aria-label="Permalink to &quot;Deployments&quot;">​</a></h2><p>One instance, or several sharing one standalone Redis and shared media storage (<a href="./../digging-deeper/instances.html">Several instances</a>). Password-hashing and upload concurrency limits are per instance; runtime branding is cached per instance, and each instance runs its own realtime hubs.</p><h2 id="size" tabindex="-1">Size <a class="header-anchor" href="#size" aria-label="Permalink to &quot;Size&quot;">​</a></h2><p>The panel ships as one JavaScript file of about 1.36 MB (about 417 KB gzipped) and one stylesheet of about 42 KB (about 8 KB gzipped), embedded in the binary. The server sends them uncompressed, with a one-year immutable cache: put a compressing reverse proxy in front if the first load matters. Binary sizes depend on the features and drivers you build with; measure your own release build.</p>',16)])])}const p=t(r,[["render",s]]);export{u as __pageData,p as default};
